mapper.insert:
INSERT INTO API_Q
    ( COMPANY        /* _1- */
    , URL            /* _2- */
    , HEADERS        /* _3- */
    , QUERYPARAMS    /* _4- */
    , TABLENAME      /* _5- */
    , SUBTABLE       /* _6- */
    , REQUEST        /* _7- */
    , API_KEY        /* _8- */
    , KEY_VALUE      /* _9- */
    , SUB_KEY_VALUE  /* _10- */
    , PG_NM          /* _11- */
    )
VALUES
    ( #{company, jdbcType=VARCHAR}
    , #{url, jdbcType=VARCHAR}
    , #{headers, jdbcType=VARCHAR}
    , #{qValue, jdbcType=VARCHAR}
    , #{tablename, jdbcType=VARCHAR}
    , #{subtable, jdbcType=VARCHAR}
    , '0'
    , TO_CHAR(sysdate, 'yyyymmdd') || '-' || RAWTOHEX(SYS_GUID())
    , #{keyValue, jdbcType=VARCHAR}
    , #{subKeyValue, jdbcType=VARCHAR}
    , 'W_API_PARAMS'
    )
